INSERT INTO `berita` (`id`, `judul`, `slug`, `isi`, `gambar`, `kategori`, `author`, `status`, `created_at`, `updated_at`, `dibaca`, `dishare`) VALUES (5,'Perkuat Database Keanggotaan, PGNI Lampung Luncurkan Portal Digital Resmi untuk Berdayakan Guru Ngaji','perkuat-database-keanggotaan-pgni-lampung-luncurkan-portal-digital-resmi-untuk-berdayakan-guru-ngaji','Perkuat Database Keanggotaan, PGNI Lampung Luncurkan Portal Digital Resmi untuk Berdayakan Guru Ngaji\r\n\r\nBANDAR LAMPUNG — Pengurus Wilayah Persatuan Guru Ngaji Indonesia (PGNI) Provinsi Lampung secara resmi meluncurkan portal digital keanggotaan melalui situs web https://pgni.net/. Langkah strategis ini diambil sebagai bagian dari komitmen organisasi dalam melakukan digitalisasi data guna meningkatkan kesejahteraan dan kompetensi para pengajar Al-Qur\'an di seluruh pelosok Provinsi Lampung.\r\n\r\nSebagai organisasi profesi yang menghimpun para ustadz, ustadzah, serta pengajar Taman Pendidikan Al-Qur\'an (TPA) dan Madrasah Diniyah Takmiliyah Awaliyah (MDTA), PGNI Lampung menyadari pentingnya memiliki basis data (database) yang akurat, transparan, dan terintegrasi.\r\n\r\n\"Guru ngaji adalah ujung tombak dalam mencetak generasi Qur’ani yang berakhlak mulia di Lampung. Kehadiran portal digital ini bertujuan memudahkan para pengajar Al-Qur\'an mendaftarkan diri secara mandiri, sehingga kami dapat memiliki peta persebaran guru ngaji yang akurat di seluruh Kabupaten dan Kota,\" ungkap perwakilan pengurus PGNI Lampung.\r\n\r\nMelalui portal ini, para guru ngaji di Provinsi Lampung dapat memanfaatkan berbagai fitur utama, antara lain:\r\n\r\nRegistrasi Anggota Online: Kemudahan pendaftaran keanggotaan dari mana saja tanpa perlu terkendala jarak fisik.\r\n\r\nCek Status Verifikasi: Fitur transparan untuk memantau kemajuan proses pendaftaran keanggotaan.\r\n\r\nPusat Informasi Terpadu: Portal informasi terkait program peningkatan kapasitas pengajar, berita kegiatan sosial, hingga program bantuan/insentif kesejahteraan.\r\n\r\nKehadiran basis data yang mutakhir ini diharapkan dapat memudahkan kolaborasi sinergis antara PGNI Lampung dengan pemerintah daerah maupun lembaga filantropi. Dengan data keanggotaan yang valid, penyaluran program bantuan kesejahteraan, insentif, maupun sertifikasi kompetensi guru ngaji dapat dilakukan secara lebih tepat sasaran dan berkesinambungan.\r\n\r\nPengurus PGNI Provinsi Lampung mengimbau dan mengajak seluruh guru ngaji, ustadz, ustadzah, serta pengelola TPA/MDTA se-Provinsi Lampung untuk segera mengunjungi laman resmi https://pgni.net/ guna melakukan pendaftaran dan menjadi bagian dari gerakan bersama memajukan pendidikan Al-Qur\'an di Lampung.\r\n\r\nTentang PGNI Lampung:\r\nPersatuan Guru Ngaji Indonesia (PGNI) Provinsi Lampung adalah organisasi profesi yang berkomitmen menghimpun dan memperjuangkan hak-hak kesejahteraan, legalitas, serta peningkatan kompetensi para guru ngaji dan pengajar Al-Qur\'an demi melahirkan generasi yang Qur’ani di wilayah Provinsi Lampung.','perkuat_database_keanggotaan_pgni_lampung_luncurkan_portal_digital_resmi_untuk_berdayakan_guru_ngaji__berita_20260715_164129.jpg','Artikel','PGNI',0,'2026-07-15 16:41:29','2026-07-31 16:29:13',110,57),
(8,'Fitur Utama Portal Web PGNI Lampung','fitur-utama-portal-web-pgni-lampung','Portal digital PGNI Lampung dirancang secara khusus untuk memperkuat pangkalan data (*database*) keanggotaan serta memberikan ruang pemberdayaan bagi para guru ngaji, ustadz/ustadzah, dan pengajar Al-Qur\'an (TPA/TPQ/MDTA/Rumah Pribadi).\r\n\r\n**Fitur Utama Portal Web PGNI Lampung**\r\n\r\n1. **Registrasi Anggota Online (*Member Registration*):** Memudahkan guru ngaji di seluruh Kabupaten/Kota se-Provinsi Lampung untuk mendaftarkan diri secara mandiri dan cepat melalui portal digital.\r\n2. **Sistem Cek Status Anggota:** Fitur pencarian instan untuk memverifikasi keaktifan dan status keanggotaan guru ngaji yang terdaftar di dalam pangkalan data.\r\n3. **Portal Informasi & Berita Terintegrasi:** Ruang publikasi untuk membagikan info kegiatan, artikel keagamaan, dan perkembangan terkini seputar dunia pendidikan Al-Qur\'an di Lampung.\r\n4. **Pangkalan Data Guru Ngaji (Database Guru):** Memetakan lokasi mengajar (baik di TPA, TPQ, MDTA, masjid, maupun les privat rumah pribadi) secara rapi dan transparan demi memudahkan pembinaan.\r\n\r\n **Manfaat Bergabung bagi Guru Ngaji & Pengajar Al-Qur\'an**\r\n\r\n1. **Sinergi & Ukhuwah:** \r\nMenjadi bagian dari jaringan resmi Persatuan Guru Ngaji Indonesia yang menghimpun para pendidik Al-Qur\'an di tingkat regional Lampung hingga nasional.\r\n\r\n2. **Peningkatan Kualitas & Kompetensi:** \r\nMendapatkan kesempatan untuk mengikuti berbagai program pembinaan, pelatihan, serta standardisasi metode pengajaran Al-Qur\'an.\r\n3. **Advokasi & Kesejahteraan:** \r\nBerpartisipasi dalam program kerja PGNI yang berfokus memperjuangkan kesejahteraan, apresiasi, dan perlindungan profesi bagi guru ngaji.\r\n4. **Akses Program Pemberdayaan:** \r\nTerbuka ruang untuk mendapatkan penyaluran bantuan sarana mengajar, program kolaborasi keumatan, serta berbagai program sosial-keagamaan lainnya.','fitur_utama_portal_web_pgni_lampung__berita_20260715_180336.png','Pengumuman','PGNI',0,'2026-07-15 18:03:36','2026-07-31 16:43:35',751,84),
(9,'Cara Mudah Cek Status Pendaftaran Anggota PGNI Lampung Secara Online','cara-mudah-cek-status-pendaftaran-anggota-pgni-lampung-secara-online','Bagi para guru dan tenaga kependidikan di wilayah Lampung yang telah melakukan pendaftaran keanggotaan Persatuan Guru Ngaji Indonesia (PGNI), kini Anda dapat memantau status verifikasi berkas secara mandiri dan cepat melalui portal resmi **pgni.net**.\r\n\r\nLayanan ini dirancang untuk memberikan transparansi informasi serta kemudahan akses bagi seluruh calon anggota tanpa harus datang langsung ke kantor sekretariat.\r\n\r\nLangkah-Langkah Melakukan Cek Status:\r\n\r\n1. **Akses Portal Resmi**\r\nBuka web browser di perangkat handphone atau komputer Anda, lalu kunjungi laman khusus pengecekan di: https://pgni.net/pgnil/cek_status.php\r\n\r\n2. **Input NIK Anda**\r\nPada kolom pencarian yang tersedia, masukkan **16 digit Nomor Induk Kependudukan (NIK) sesuai dengan yang tertera pada KTP asli Anda. Pastikan input berupa angka murni tanpa spasi atau karakter penghubung.\r\n\r\n3. **Klik \"Cek Status\"**\r\nKlik tombol hijau bertuliskan **\"Cek Status\"**. Sistem akan otomatis memindai basis data dan menampilkan informasi status keanggotaan Anda saat ini.\r\n\r\n\r\nTanya Jawab Umum (FAQ) Seputar Pendaftaran PGNI Lampung\r\n\r\nUntuk membantu menjawab kebingungan calon anggota, berikut adalah rincian aturan dan prosedur resmi dari PGNI Lampung:\r\n\r\nBagaimana cara mendaftar jika belum memiliki akun?\r\nSilakan klik tombol **\"Daftar\"** yang terdapat pada halaman utama atau menu registrasi di website resmi PGNI Lampung untuk mengisi formulir pendaftaran baru.\r\n\r\n* **Berapa lama proses verifikasi berkas dilakukan?**\r\nTim verifikator admin membutuhkan waktu maksimal **1x24 jam** hari kerja terhitung setelah Anda berhasil mengirimkan data pendaftaran.\r\n\r\n* **Apa yang harus dilakukan jika status pendaftaran saya \"Ditolak\"?**\r\nJangan khawatir, jika status ditolak silakan hubungi admin PGNI Lampung secara langsung melalui **halaman kontak** yang tersedia di situs web untuk mendapatkan petunjuk perbaikan dokumen Anda.\r\n\r\n* **Apakah pendaftaran anggota ini dipungut biaya?**\r\nPendaftaran untuk menjadi anggota PGNI Lampung sepenuhnya **GRATIS** dan bebas dari biaya administrasi apa pun. Mohon berhati-hati terhadap oknum yang meminta imbalan finansial atas nama organisasi.','1784179160_2299.png','','PGNI',0,'2026-07-16 05:11:14','2026-07-31 10:36:16',99,6),
(10,'Digitalisasi Data Guru Ngaji: Ratusan Pendidik Al-Qur\'an Mulai Terdata di Portal Web PGNI Lampung','digitalisasi-data-guru-ngaji-ratusan-pendidik-al-qur-an-mulai-terdata-di-portal-web-pgni-lampung','Digitalisasi Data Guru Ngaji: Ratusan Pendidik Al-Qur\'an Mulai Terdata di Portal Web PGNI Lampung\r\n\r\n**LAMPUNG** – \r\nLangkah maju diambil oleh Persatuan Guru Ngaji Indonesia (PGNI) Wilayah Lampung dalam menata dan meningkatkan kesejahteraan para pendidik Al-Qur\'an. Melalui peluncuran portal web resminya, proses registrasi dan pendataan guru ngaji di seluruh klaster wilayah Lampung kini terintegrasi secara digital.\r\n\r\nHingga hari ini, antusiasme para guru ngaji untuk mendaftarkan diri tergolong sangat tinggi. Sistem *dashboard* Super Admin PGNI Lampung mencatat lonjakan data yang signifikan dari 15 kabupaten/kota yang tersebar di seluruh wilayah Provinsi Lampung.\r\n\r\n**Statistik Terkini Pendaftaran Guru Ngaji**\r\n\r\nBerdasarkan data *real-time* dari portal web PGNI Lampung, berikut adalah rangkuman statistik pendaftaran secara global:\r\n\r\n* **Total Guru Ngaji Terdaftar:** 126 Orang\r\n* **Guru Aktif:** 126 Orang\r\n* **Sudah Diverifikasi:** 52 Orang\r\n* **Menunggu Verifikasi:** 69 Orang\r\n\r\nProses verifikasi saat ini sedang berjalan ketat untuk memastikan kevalidan data para pengajar sebelum nantinya mereka mendapatkan program-program pembinaan dan advokasi lebih lanjut dari pengurus PGNI.\r\n\r\n **Peta Persebaran Pendaftar di 15 Kabupaten/Kota**\r\n\r\nDigitalisasi ini mencakup seluruh wilayah Lampung guna memastikan tidak ada guru ngaji di pelosok desa yang luput dari pendataan. Berikut adalah rincian jumlah guru ngaji yang telah terdaftar di masing-masing daerah:\r\n\r\n| Kabupaten / Kota | Jumlah Guru Terdaftar | Jumlah Kecamatan | Jumlah Desa |\r\n| --- | --- | --- | --- |\r\n| **Pesawaran** | 44 | 11 | 144 |\r\n| **Pesisir Barat** | 28 | 11 | 118 |\r\n| **Bandar Lampung** | 22 | 20 | 125 |\r\n| **Lampung Tengah** | 15 | 28 | 314 |\r\n| **Lampung Selatan** | 6 | 17 | 260 |\r\n| **Lampung Utara** | 3 | 23 | 247 |\r\n| **Way Kanan** | 3 | 15 | 227 |\r\n| **Lampung Barat** | 2 | 15 | 136 |\r\n| **Lampung Timur** | 1 | 24 | 264 |\r\n| **Tanggamus** | 1 | 20 | 302 |\r\n| **Metro** | 1 | 5 | 22 |\r\n| **Mesuji** | 0 | 7 | 105 |\r\n| **Pringsewu** | 0 | 9 | 131 |\r\n| **Tulang Bawang** | 0 | 15 | 151 |\r\n| **Tulang Bawang Barat** | 0 | 9 | 96 |\r\n\r\n> *Catatan: Beberapa kabupaten dengan angka pendaftaran \"0\" diharapkan segera menyusul seiring dengan sosialisasi masif yang terus digencarkan oleh tim pengurus di tingkat daerah.*\r\n\r\nLangkah Strategis Menuju Kesejahteraan Umat\r\n\r\nHadirnya portal web ini bukan sekadar urusan administratif. Data yang valid akan menjadi instrumen penting bagi PGNI Lampung untuk memperjuangkan hak-hak para guru ngaji, mulai dari standarisasi kompetensi, jaminan sosial, hingga program insentif dari pemerintah maupun lembaga filantropi.\r\n\r\nAdmin wilayah mengimbau kepada seluruh pengurus cabang dan para guru ngaji yang belum sempat melakukan registrasi agar segera mengakses portal web resmi PGNI Lampung. Dengan gotong royong digital ini, syiar Al-Qur\'an di Bumi Ruwa Jurai diharapkan semakin kuat, terstruktur, dan bermartabat.','digitalisasi_data_guru_ngaji_ratusan_pendidik_alquran_mulai_terdata_di_portal_web_pgni_lampung__berita_20260717_141333.png','Artikel','PGNI Lampung',0,'2026-07-17 14:13:33','2026-07-31 16:39:29',140,32),
(11,'PGNI Lampung Perjuangkan Insentif Untuk Guru Ngaji','pgni-lampung-perjuangkan-insentif-untuk-guru-ngaji','Dalam rangka mengapresiasi salah satu pilar penting pendidikan dan mendukung terwujudnya masyarakat yang religius dalam visi pembangunan, Persatuan Guru Ngaji Indonesia (PGNI) merasa terketuk dan tergerak untuk membantu memperjuangkan nasib para guru ngaji yang kesejahtraan mereka dinilai saat ini masih kurang.\r\n\r\nPGNI saat ini telah membuat website dan aplikasi yang canggih sebagai sarana untuk memberikan berita terbaru, mendata dan mendistribusikan insentif guru ngaji.\r\n\r\nPengurus PGNI Provinsi Lampung mengimbau dan mengajak seluruh guru ngaji, Marbot, Penjaga Makam/Juru Kunci, serta pengelola TPA/TPQ, MDTA se-Provinsi Lampung untuk segera mengunjungi laman resmi PGNI.NET guna melakukan pendaftaran','1784738707_4737.jpg','Artikel','PGNI Lampung',0,'2026-07-18 03:38:36','2026-07-31 12:59:21',468,13),
(12,'📰 Berita Resmi PGNI Lampung','berita-resmi-pgni-lampung','Fitur Login Guru Ngaji Kini Hadir di PGNI.net, Permudah Pendataan & Layanan Digital\r\n\r\n**Bandar Lampung** – Kabar gembira bagi seluruh guru ngaji di Provinsi Lampung. Kini, website resmi **PGNI Lampung (Persatuan Guru Ngaji Indonesia)** telah menghadirkan **fitur login khusus guru ngaji** yang dapat diakses melalui platform digital **PGNI.net**.\r\n\r\nPeluncuran fitur ini merupakan langkah nyata dalam mendukung transformasi digital organisasi serta meningkatkan pelayanan kepada para anggota di seluruh wilayah Lampung. \r\n\r\n📌 Mempermudah Akses & Pendataan Guru Ngaji\r\n\r\nDengan hadirnya fitur login ini, setiap guru ngaji yang telah terdaftar kini dapat:\r\n\r\n* Mengakses **akun pribadi (member area)\r\n* Melihat dan mengelola **data diri secara mandiri\r\n* Mendapatkan **Kartu Tanda Anggota (KTA) digital\r\n* Mengunduh **sertifikat resmi keanggotaan \r\n* Memantau status verifikasi keanggotaan\r\n\r\nLangkah ini sejalan dengan upaya peningkatan kualitas pendataan guru ngaji yang selama ini menjadi bagian penting dalam pembangunan pendidikan keagamaan di masyarakat. Peran guru ngaji sendiri sangat vital dalam membentuk generasi berakhlak dan religius\r\n\r\n🪪 Digitalisasi KTA & Sertifikat\r\n\r\nMelalui sistem terbaru ini, anggota tidak lagi harus menunggu proses manual. Semua layanan kini tersedia secara **instan dan digital**, di antaranya:\r\n\r\n* KTA Digital** lengkap dengan QR Code\r\n* Sertifikat Anggota** dengan desain islami resmi\r\n* Fitur  cetak langsung atau simpan PDF\r\n\r\nHal ini memudahkan guru ngaji dalam berbagai keperluan administratif maupun kegiatan organisasi.\r\n\r\n🌐 Dukungan untuk Guru Ngaji di Era Digital\r\n\r\nPGNI Lampung terus berkomitmen untuk menjadi wadah profesional bagi para guru ngaji. Dengan adanya fitur login ini, diharapkan:\r\n\r\n* Proses administrasi menjadi lebih cepat dan transparan\r\n* Data anggota lebih akurat dan terintegrasi\r\n* Guru ngaji semakin mudah mendapatkan pengakuan resmi\r\n\r\nSelain itu, digitalisasi ini juga menjadi bagian dari adaptasi terhadap perkembangan teknologi, sehingga organisasi tetap relevan di era modern.\r\n\r\n🤝 Harapan ke Depan\r\n\r\nPengurus PGNI Lampung berharap seluruh guru ngaji di kabupaten/kota dapat segera memanfaatkan fitur ini. Ke depan, sistem ini juga akan terus dikembangkan dengan berbagai fitur tambahan seperti:\r\n\r\n* Informasi kegiatan & pelatihan\r\n* Berita dan artikel keislaman\r\n* Layanan komunikasi antar anggota\r\n\r\n📣 Penutup\r\n\r\nDengan hadirnya fitur login guru ngaji di PGNI.net, kini seluruh anggota dapat merasakan kemudahan layanan dalam satu genggaman. Ini menjadi langkah awal menuju **organisasi guru ngaji yang modern, profesional, dan terintegrasi secara digital**.','berita_resmi_pgni_lampung__berita_20260718_204317.jpg','Informasi','PGNI Lampung',0,'2026-07-18 20:23:42','2026-07-31 16:37:27',204,9),
(17,'📘 Apa Itu pgni.net?','apa-itu-pgni-net','pgni.net adalah portal digital resmi Persatuan Guru Ngaji Indonesia (PGNI) Provinsi Lampung yang dirancang untuk mendukung pengelolaan data, informasi, dan pemberdayaan guru ngaji secara terintegrasi.\r\n\r\nPlatform ini hadir sebagai solusi modern dalam mendata guru ngaji di seluruh wilayah Lampung, sekaligus menjadi pusat informasi dan koordinasi antar pengurus di tingkat desa, kecamatan, hingga kabupaten.\r\n\r\nDengan memanfaatkan teknologi digital, pgni.net membantu meningkatkan kualitas administrasi, transparansi data, serta mempermudah akses informasi bagi seluruh anggota organisasi.\r\n\r\n🎯 Tujuan dan Manfaat pgni.net\r\n\r\nPortal ini dibangun dengan beberapa tujuan utama, antara lain:\r\n\r\nMempermudah pendataan guru ngaji secara terpusat\r\nMendukung pengelolaan administrasi yang rapi dan efisien\r\nMenyediakan informasi kegiatan dan berita terbaru\r\nMeningkatkan kualitas pelayanan organisasi PGNI\r\nMendorong pemberdayaan guru ngaji berbasis digital\r\n\r\nDengan adanya sistem ini, diharapkan seluruh guru ngaji di Lampung dapat terdata secara resmi dan mendapatkan perhatian serta pembinaan yang lebih baik.\r\n\r\n⚙️ Fungsi Utama Sistem\r\n\r\nBeberapa fitur utama dari pgni.net meliputi:\r\n\r\n1. Pendataan Guru Ngaji\r\n\r\nMencatat identitas lengkap guru ngaji, termasuk lokasi mengajar dan informasi penting lainnya.\r\n\r\n2. Manajemen Wilayah\r\n\r\nSistem dikelola oleh admin di setiap wilayah untuk memastikan data selalu valid dan terupdate.\r\n\r\n3. Informasi & Berita\r\n\r\nMenyediakan berbagai informasi kegiatan, pengumuman, dan berita terbaru dari PGNI Lampung.\r\n\r\n4. Statistik & Laporan\r\n\r\nMenampilkan data dalam bentuk grafik dan laporan untuk memudahkan analisis perkembangan.\r\n\r\n5. Dokumen & Administrasi\r\n\r\nMendukung pengelolaan dokumen seperti KTA, sertifikat, dan arsip digital lainnya.\r\n\r\n🔄 Alur Pendataan Guru Ngaji\r\n\r\n\r\nProses pendataan dalam sistem pgni.net dilakukan melalui beberapa tahap:\r\n\r\nPetugas login ke sistem\r\nInput data guru ngaji\r\nVerifikasi oleh admin wilayah\r\nData tersimpan resmi di sistem PGNI\r\n\r\nAlur ini memastikan bahwa setiap data yang masuk telah diverifikasi dan dapat dipertanggungjawabkan.\r\n\r\n📱 Akses Mudah & Keamanan Data\r\n\r\npgni.net dirancang agar dapat diakses melalui berbagai perangkat, seperti:\r\nDesktop\r\nLaptop\r\nTablet\r\nSmartphone\r\n\r\nSelain itu, sistem ini juga dilengkapi dengan fitur keamanan data untuk melindungi informasi pengguna, termasuk backup rutin dan sistem proteksi data.\r\n\r\n🌐 Kesimpulan\r\n\r\npgni.net merupakan langkah maju dalam digitalisasi organisasi keagamaan, khususnya dalam pengelolaan guru ngaji di Provinsi Lampung. Dengan sistem ini, PGNI tidak hanya mempermudah administrasi, tetapi juga memperkuat jaringan dan kontribusi guru ngaji dalam membangun generasi Qur’ani yang berakhlak mulia.','apa_itu_pgninet__berita_20260719_061801.jpg','Informasi','PGNI Lampung',0,'2026-07-19 06:18:01','2026-07-31 15:57:07',188,32),
(18,'🚀 Dukung Percepatan Proyeksi Chatbot WhatsApp PGNI!','dukung-percepatan-proyeksi-chatbot-whatsapp-pgni','Halo Sahabat PGNI,\r\n\r\nSaat ini pengembangan Chatbot WhatsApp PGNI terus berjalan untuk menghadirkan kemudahan layanan informasi, registrasi, hingga pembaruan data secara otomatis! 📱🤖\r\n\r\nAgar proyeksi ini berjalan lancar dan cepat direalisasikan, kami sangat mengharapkan dukungan moril, spiritual, serta materiil dari rekan-rekan sekalian.\r\n\r\nMari menjadi bagian dari kemajuan ini dengan berdonasi melalui link di bawah ini:\r\n\r\n👉  https://www.pgni.net/pgnil/donasi.php\r\n\r\nDukungan dan doa dari Anda sangat berarti bagi pengembangan PGNI. Terima kasih! 🙏','1785323849_6565.jpg','Informasi','PGNI Lampung',0,'2026-07-29 10:03:38','2026-07-31 16:54:10',123,11),
(21,'🚀 *Dukung Percepatan Proyeksi Chatbot WhatsApp PGNI!*','dukung-percepatan-proyeksi-chatbot-whatsapp-pgni','Halo Sahabat PGNI,\r\n\r\nSaat ini pengembangan Chatbot WhatsApp PGNI terus berjalan untuk menghadirkan kemudahan layanan informasi, registrasi, hingga pembaruan data secara otomatis! 📱🤖\r\n\r\nAgar proyeksi ini berjalan lancar dan cepat direalisasikan, kami sangat mengharapkan dukungan moril, spiritual, serta materiil dari rekan-rekan sekalian.\r\n\r\nMari menjadi bagian dari kemajuan ini dengan berdonasi melalui link di bawah ini:\r\n\r\n👉  https://www.pgni.net/pgnil/donasi.php\r\n\r\nDukungan dan doa dari Anda sangat berarti bagi pengembangan PGNI. Terima kasih! 🙏','dukung_percepatan_proyek_chatbot_whatsapp_pgni__berita_20260729_114546.jpg','Informasi','PGNI Lampung',0,'2026-07-29 11:45:46','2026-07-31 13:00:24',33,6);
INSERT INTO `chat_logs` (`id`, `session_id`, `sender`, `message`, `created_at`) VALUES (1,'user_1785076575462_w9bvp4eqt','user','User: basuki rahmat (Belum Terdaftar)','2026-07-30 14:13:15'),
(2,'user_1785076575462_w9bvp4eqt','bot','Assalamu\'alaikum warahmatullahi wabarakatuh! 👋<br><br>Selamat datang di PGNI Lampung, <strong>basuki rahmat</strong>! 🙏<br><br>📝 Saya senang bisa berkenalan dengan Anda.<br>Ada yang bisa saya bantu terkait PGNI Lampung?<br><br>💡 <strong>Pertanyaan yang bisa diajukan:</strong><br>• 📝 <strong>Registrasi</strong> - Panduan mendaftar member PGNI<br>• 🔍 <strong>Cek Status</strong> - Cek status pendaftaran Anda<br>• 📞 <strong>Kontak</strong> - Alamat dan kontak PGNI<br>• ⚖️ <strong>Legalitas</strong> - Informasi badan hukum PGNI','2026-07-30 14:13:15'),
(3,'user_1785076575462_w9bvp4eqt','user','cara daftar','2026-07-30 14:13:18'),
